{
  "observed_defect": "Ground lacks natural prairie relief; uniform flatness violates strategy-camera legibility and architectural intent, with no camera-visible asymmetrical landforms or connected valleys.",
  "design_intent": "Create three broad, asymmetrical gentle landforms with connected valleys and open prairie between them, avoiding isolated mounds and rigid waves, preserving city boundary and using only vertical delta [0,0,dz] sculpting.",
  "asset_decision": "MODIFY",
  "reason_for_new_geometry": "Required to meet visual and functional criteria for strategy-game camera legibility and natural geography without altering approved assets.",
  "planned_actions": [
    {
      "id": "sculpt_region",
      "type": "sculpt_region",
      "target": "ZoneOne continuous prairie source",
      "rationale": "Create broad asymmetrical landform with vertical delta [0,0,7.0] at center, preserving boundary constraints.",
      "parameters": {
        "radius": 30,
        "knots": [
           {
            "center": [0.0, 0.0, 0.0],
            "delta": [0.0, 0.0, 7.0],
            "radius": 30
          },
          {
            "center": [0.0, 0.0, 0.0],
            "delta": [0.0, 0.0, 7.0],
            "radius": 30
          }
        ]
      }
    },
    {
      "id": "sculpt_path",
      "type": "sculpt_path",
      "target": "ZoneOne continuous prairie source",
      "rationale": "Define valley path between two landforms with vertical delta [0,0,3.0] and radius 25, avoiding city boundary.",
      "parameters": {
        "radius": 25,
        "knots": [
          {
            "center": [-60.0, 0.0, 0.0],
            "delta": [0.0, 0.0, 3.0],
            "radius": 25
          },
          {
            "center": [60.0, 0.0, 0.0],
            "delta": [0.0, 0.0, 3.0],
            "radius": 25
          }
        ]
      }
    },
    {
      "id": "sculpt_region",
      "type": "sculpt_region",
      "target": "ZoneOne continuous prairie source",
      "rationale": "Create third broad landform with vertical delta [0,0,6.0] at 45° angle, preserving boundary constraints.",
      "parameters": {
        "radius": 35,
        "knots": [
          {
            "center": [0.0, 45.0, 0.0],
            "delta": [0.0, 0.0, 6.0],
            "radius": 35
          },
          {
            "center": [0.0, 45.0, 0.0],
            "delta": [0.0, 0.0, 6.0],
            "radius": 35
          }
        ]
      }
    }
  ],
  "expected_visual_difference": "Three broad, asymmetrical landforms with connected valleys and open prairie between them, avoiding isolated mounds and rigid waves.",
  "mobile_risks": "Low; all edits within vertical delta [0,0,dz] and boundary constraints; no vertex index operations or topology changes."
}
